class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        self.s, self.i = expression, 0

        def expr():
            cur = {''}
            while self.i < len(self.s) and (self.s[self.i].isalpha() or self.s[self.i] == '{'):
                cur = {a + b for a in cur for b in item()}
            return cur

        def item():
            if self.s[self.i] == '{':
                self.i += 1
                res = set()
                while True:
                    res |= expr()
                    if self.s[self.i] == ',':
                        self.i += 1
                    else:
                        break
                self.i += 1
                return res
            c = self.s[self.i]
            self.i += 1
            return {c}

        return sorted(expr())

