class Solution {
    private String s;
    private int i;

    public List<String> braceExpansionII(String expression) {
        s = expression; i = 0;
        TreeSet<String> r = expr();
        return new ArrayList<>(r);
    }

    private TreeSet<String> expr() {
        TreeSet<String> cur = new TreeSet<>();
        cur.add("");
        while (i < s.length() && (Character.isLowerCase(s.charAt(i)) || s.charAt(i) == '{')) {
            TreeSet<String> nxt = item(), prod = new TreeSet<>();
            for (String a : cur)
                for (String b : nxt)
                    prod.add(a + b);
            cur = prod;
        }
        return cur;
    }

    private TreeSet<String> item() {
        TreeSet<String> res = new TreeSet<>();
        if (s.charAt(i) == '{') {
            i++;
            while (true) {
                res.addAll(expr());
                if (s.charAt(i) == ',') i++; else break;
            }
            i++;
        } else {
            res.add(String.valueOf(s.charAt(i++)));
        }
        return res;
    }
}

