        const res = new Set();
        if (s[i] === '{') {
            i++;
            while (true) {
                for (const w of expr()) res.add(w);
                if (s[i] === ',') i++; else break;
            }
            i++;
        } else {
            res.add(s[i++]);
        }
        return res;
    }

    return [...expr()].sort();
};

