class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        stack = [[set(), []]]  # [current concat set, alternatives]
        for ch in expression:
            if ch.isalpha():
                stack[-1][0] = {w + ch for w in stack[-1][0]} if stack[-1][0] else {ch}
            elif ch == '{':
                stack.append([set(), []])
            elif ch == ',':
                stack[-1][1].append(stack[-1][0])
                stack[-1][0] = set()
            else:  # '}'
                stack[-1][1].append(stack[-1][0])
                union = set().union(*stack.pop()[1])
                outer = stack[-1]
                outer[0] = {a + b for a in outer[0] for b in union}
        return sorted(stack[0][0])

