class Solution {
public:
    vector<string> braceExpansionII(string expression) {
        struct Scope { set<string> cur; vector<set<string>> alts; };
        vector<Scope> st(1);
        for (char ch : expression) {
            if (isalpha(ch)) {
                set<string> nxt;
                if (st.back().cur.empty()) nxt.insert(string(1, ch));
                else for (auto &w : st.back().cur) nxt.insert(w + ch);
                st.back().cur = move(nxt);
            } else if (ch == '{') {
                st.push_back({{}, {}});
            } else if (ch == ',') {
                st.back().alts.push_back(move(st.back().cur));
                st.back().cur.clear();
            } else {
                st.back().alts.push_back(move(st.back().cur));
                set<string> u;
                for (auto &alt : st.back().alts) u.insert(alt.begin(), alt.end());
                st.pop_back();
                set<string> nxt;
                for (auto &a : st.back().cur)
                    for (auto &b : u) nxt.insert(a + b);
                st.back().cur = move(nxt);
            }
        }
        return vector<string>(st[0].cur.begin(), st[0].cur.end());
    }
};

