class Solution {
    public List<String> braceExpansionII(String expression) {
        class Scope { Set<String> cur = new HashSet<>(); List<Set<String>> alts = new ArrayList<>(); }
        Deque<Scope> st = new ArrayDeque<>();
        st.push(new Scope());
        for (char ch : expression.toCharArray()) {
            Scope top = st.peek();
            if (Character.isLowerCase(ch)) {
                Set<String> nxt = new HashSet<>();
                if (top.cur.isEmpty()) nxt.add(String.valueOf(ch));
                else for (String w : top.cur) nxt.add(w + ch);
                top.cur = nxt;
            } else if (ch == '{') {
                st.push(new Scope());
            } else if (ch == ',') {
                top.alts.add(top.cur);
                top.cur = new HashSet<>();
            } else {
                top.alts.add(top.cur);
                Set<String> u = new HashSet<>();
                for (Set<String> alt : top.alts) u.addAll(alt);
                st.pop();
                Scope outer = st.peek();
                Set<String> nxt = new HashSet<>();
                for (String a : outer.cur)
                    for (String b : u) nxt.add(a + b);
                outer.cur = nxt;
            }
        }
        List<String> res = new ArrayList<>(st.peek().cur);
        Collections.sort(res);
        return res;
    }
}

